def run(session, query, top_k):
    import re

    # Split query on ' and ' or commas, strip whitespace
    parts = [p.strip() for p in re.split(r'\s+and\s+|,', query) if p.strip()]

    results = []

    for part in parts:
        # Decide mode based on heuristics
        # If part contains named entity hints, use store.query_fielded
        # Named entity hints: words like 'who', 'which', 'name', 'actor', 'politician', 'publisher', 'cities', 'title'
        # Otherwise use hybrid search
        # Always include a hyde_search for coverage

        part_lower = part.lower()
        named_entity_keywords = ['who', 'which', 'name', 'actor', 'politician', 'publisher', 'cities', 'title', 'box set', 'novel', 'series']

        if any(k in part_lower for k in named_entity_keywords):
            # Named entity search
            try:
                res_fielded = session.store.query_fielded(part, ['title', 'text'], top_k=top_k)
            except Exception:
                res_fielded = None
            if res_fielded:
                results.append(res_fielded)
        else:
            # Hybrid search
            try:
                res_hybrid = session.search(part, top_k=top_k, mode='hybrid')
            except Exception:
                res_hybrid = None
            if res_hybrid:
                results.append(res_hybrid)

        # Always add hyde_search for coverage
        try:
            res_hyde = session.hyde_search(part, top_k=top_k)
        except Exception:
            res_hyde = None
        if res_hyde:
            results.append(res_hyde)

    # Fuse all result sets if more than one, else return single
    if not results:
        return []
    if len(results) == 1:
        return results[0]
    fused = session.fuse(results)
    return fused
